(() => {
  const clean = (v) => String(v == null ? "" : v).replace(/\s+/g, " ").trim();
  const body = clean(document.body && document.body.innerText);
  const lines = Array.from(document.querySelectorAll("[data-lineitemtype]")).map((card) => ({
    type: card.getAttribute("data-lineitemtype"),
    itemId: card.getAttribute("data-itemid"),
    description: clean((card.querySelector("[id$='_ItemDescription']") || {}).innerText),
    price: clean((card.querySelector(".itemPrice b") || {}).innerText),
  }));
  const total = /Transaction grand total\s*([0-9][0-9,]*\.[0-9]{2})/.exec(body);
  const payLater = document.querySelector("input[name$='PaymentMethodRadioButtonList'][value='BillMe']");
  const suppress = document.querySelector("input[id$='_SuppressEmailCheckbox']");
  const submit = document.querySelector("input[id$='_SubmitCartOrderButton']");
  return {
    href: location.href,
    empty: /There are no items in the cart/.test(body),
    lines,
    grandTotal: total ? total[1].replace(/,/g, "") : null,
    payLaterChecked: payLater ? payLater.checked === true : null,
    suppressEmailChecked: suppress ? suppress.checked === true : null,
    submitShown: Boolean(submit),
  };
})()`,RBn=String['raw']`
